import type { LocaleCode } from "./i18n";

/**
 * Panel catalog, gettext-style: the English source string IS the key.
 *
 * The alternative — a symbolic key per string — drifts the moment someone edits the English
 * copy without touching the key, and the panel then shows a stale translation. Here an edited
 * English string simply misses the catalog and falls back to itself, which is visible and
 * honest. The Trust section reports the coverage measured from the render that just happened,
 * so it can never claim more than the panel actually shows in that locale.
 *
 * GENERATED — do not hand-edit the key order. `node tools/i18n-extract.mjs --write` mounts the
 * panel in a real browser and reports what it renders, which is where `PANEL_STRINGS` and the
 * per-locale key sets come from; they therefore cannot drift from what the UI asks for.
 * All nine locales are complete. `tests/i18n.test.mjs` fails the build if one falls behind.
 */

export type PanelCatalog = Partial<Record<LocaleCode, Record<string, string>>>;

